-- FACT_REDEMPTIONCERTIFICATE.MEMBERHASHKEY   = aeropan to aeroplan


COMMENT ON TABLE DIM_BOOKINGPRODUCTTYPE IS 'Categorizes the various products Aeroplan points can be earned or redeemed through partner merchants.';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.BOOKINGPRODUCTTYPESID IS 'Surrogate key, unique identifier for each record of the dimension table';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.MERCHANTID IS 'Code used to identify the booking partner offering products/services to be redeemed by members, e.g. RO for RewardOps (eStore), CXL for CXLoyalty (Car & Hotel), UBR for Uber…';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.BOOKINGPRODUCTTYPECODE IS 'Code describing the specific product type (e.g., HOTEL, FLIGHT, GIFTCARD...)';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.BOOKINGPRODUCTTYPEHASHKEY IS 'Hash key for data integration/deduplication purposes';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.MERCHANTNAME IS 'Name of the booking partner offering products/services to be redeemed by members, e.g. RewardOps (eStore), CXLoyalty (Car & Hotel), Uber…';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.BOOKINGPRODUCTTYPENAME IS 'Name of the specific product type (e.g., "Pay yourself back", "Starbucks Stars")';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.BOOKINGBUDGETCATEGORYCODE IS 'Category code for budget/financial tracking (e.g., CONVERSION, PYB, WIFI, OTHER)';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.BOOKINGBUDGETCATEGORYNAME IS 'Full name of the budget category (e.g., Conversion, Pay yourself back, Wifi)';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.CURRENTFLAG IS 'Indicates if record is the current/active version (1=current, 0=historical)';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.DELETEDFLAG IS 'Soft delete indicator (1=deleted, 0=active)';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.SCDSTARTDATETIME IS 'Slowly Changing Dimension start date, when this version became effective';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.SCDENDDATETIME IS 'Slowly Changing Dimension end date, when this version was superseded (9999-12-31 = still current)';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.LATEARRIVINGFLAG IS 'Indicates if record arrived late in the ETL process';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.TYPE1HASH IS 'Hash for detecting Type 1 SCD changes (overwrite changes)';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.TYPE2HASH IS 'Hash for detecting Type 2 SCD changes (historical tracking changes)';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.CREATEDBATCHLOGID IS 'ETL batch ID when record was created';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.UPDATEDBATCHLOGID IS 'ETL batch ID when record was last updated';
COMMENT ON COLUMN DIM_BOOKINGPRODUCTTYPE.UPDATETYPE IS 'Type of update applied';


COMMENT ON TABLE DIM_BOOKINGNONAIRFRAUD IS 'Tracks fraud-risk attributes for non-air bookings (hotels, car rentals, vacation packages, etc.). It captures customer and transaction data at the time of booking to support fraud detection, investigation, and prevention activities.';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.BOOKINGNONAIRFRAUDSID IS 'Surrogate key - unique identifier for each dimension record';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.BOOKINGCONFIRMATIONNUMBER IS 'Booking confirmation/reference number for the non-air product';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.MERCHANTID IS 'Identifier of the merchant processing the transaction';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.BOOKINGNONAIRFRAUDHASHKEY IS 'Business key hash for identifying unique bookings';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.PHONENUMBERATBOOKING IS 'Customer phone number captured at booking time (masked - policy applied)';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.BOOKINGMEMBERNUMBER IS 'Loyalty/frequent flyer member number associated with booking (masked)';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.PNRCODE IS 'Passenger Name Record code linked to the booking (masked)';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.CURRENTFLAG IS 'Indicates if this is the current/active version of the record (1=current, 0=historical)';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.DELETEDFLAG IS 'Indicates if the record has been logically deleted (1=deleted, 0=active)';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.SCDSTARTDATETIME IS 'Timestamp when this version of the record became effective';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.SCDENDDATETIME IS 'Timestamp when this version expired (end date for SCD Type 2)';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.LATEARRIVINGFLAG IS 'Indicates if the record arrived late in the ETL process';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.TYPE1HASH IS 'Hash of Type 1 (overwrite) attributes for change detection';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.TYPE2HASH IS 'Hash of Type 2 (historical) attributes for change detection';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.CREATEDBATCHLOGID IS 'ETL batch ID that initially created this record';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.UPDATEDBATCHLOGID IS 'ETL batch ID that last updated this record';
COMMENT ON COLUMN DIM_BOOKINGNONAIRFRAUD.UPDATETYPE IS 'Type of update applied (e.g., Insert, Update, Delete)';


