COMMENT ON COLUMN Fact_BookingNonAir.PURCHASECURRENCYTYPE IS 'Form of payment (points, cash, or mixed)';
COMMENT ON COLUMN Fact_BookingNonAir.RECONCILIATIONFLAG IS 'Flag indicating if the transaction is ready to be reconciliated with the corresponging redemption invoice';
COMMENT ON COLUMN Fact_BookingNonAir.REDEMPTIONEXPENSECADAMOUNT IS 'Net cost for Aeroplan';
COMMENT ON COLUMN Fact_BookingNonAir.REFERRALFEEPERCENT IS 'Percentage of referral fee';
COMMENT ON COLUMN Fact_BookingNonAir.RULEID IS 'Redemption points pricing rule applied, driven by the Redemption Pricing Tool';
COMMENT ON COLUMN Fact_BookingNonAir.STARTLOCALDATESID IS 'Surrogate key of the reservation start date, can be joined with Dim_Date';
COMMENT ON COLUMN Fact_BookingNonAir.STARTLOCALDATETIME IS 'Start date and time of a car rental or hotel booking (timezone of the rental location)';
COMMENT ON COLUMN Fact_BookingNonAir.SUPPLIERCONFIRMATIONNUMBER IS 'Internal Booking reference number from supplier/partner';
COMMENT ON COLUMN Fact_BookingNonAir.TOTALCOSTCADAMOUNT IS 'Amount to be paid by Aeroplan to the redemption partner';
COMMENT ON COLUMN Fact_BookingNonAir.TOTALREFERRALCADAMOUNT IS 'Amount to be paid to Aeroplan';
COMMENT ON COLUMN Fact_BookingNonAir.TRANSACTIONCOUNT IS 'Indicates 1 in case of a booking transaction, -1 in case of refund and 0 in case of cancellation.';
COMMENT ON COLUMN Fact_BookingNonAir.TRANSACTIONTYPE IS 'Type of transaction: booking, cancel or refund';
COMMENT ON COLUMN Fact_BookingNonAir.UPDATEBATCHLOGID IS 'Batch ID that last updated the record';
COMMENT ON COLUMN Fact_BookingNonAir.UPDATETYPE IS 'Type of update operation (Insert, Update, etc.)';


COMMENT ON TABLE DIM_ARPARTNER IS 'References all partners having a commercial agreement with Aeroplan that enables members to accumulate, convert or redeem points for purchasing products or services provided by the partner or its affiliates. It add an additional layer of information on top of Dim_Partner specificly for Analytics and Reporting (AR) purposes.';
COMMENT ON COLUMN DIM_ARPARTNER.ARPARTNERSID IS 'Surrogate key that uniquely identifies each record in the ARPartner dimension';
COMMENT ON COLUMN DIM_ARPARTNER.ARPARTNERCODE IS '3-4 character unique code identifying the AR Partner (e.g., PCIB=CIBC, PACA=Air Canada, PAMX=AMEX)';
COMMENT ON COLUMN DIM_ARPARTNER.PARTNERCODE IS 'Composite key combining partner/sub-partner codes (e.g., AVH, XAL, IFP)';
COMMENT ON COLUMN DIM_ARPARTNER.ARSUBPARTNERCODE IS 'Code for sub-partner/division under the main partner (e.g., DVHW, DXAL)';
COMMENT ON COLUMN DIM_ARPARTNER.MARKETINGPROGRAMCODE IS 'Reserved field for marketing program linkage (currently not utilized)';
COMMENT ON COLUMN DIM_ARPARTNER.ARPARTNERNAME IS 'Full business name of the AR partner (e.g., CIBC, Air Canada, Starwood Hotels)';
COMMENT ON COLUMN DIM_ARPARTNER.ARPARTNERSECTORCODE IS 'High-level business sector: TRAVEL, FINANCE, AEROPLAN, RETAIL, OTHER ACTIVITIES';
COMMENT ON COLUMN DIM_ARPARTNER.ARPARTNERSUBSECTORCODE IS 'Detailed subsector within sector (e.g., BANKING/CREDIT, FLIGHT, HOTELS, CAR RENTAL, CRUISES)';
COMMENT ON COLUMN DIM_ARPARTNER.ARSUBPARTNERNAME IS 'Name of the sub-partner/division under the main partner';
COMMENT ON COLUMN DIM_ARPARTNER.ARSUBPARTNERTYPE IS 'Relationship type: "Division" (internal unit) or "Affiliate" (external partner)';
COMMENT ON COLUMN DIM_ARPARTNER.ARSUBPARTNERSECTORCODE IS 'Sector classification at sub-partner level';
COMMENT ON COLUMN DIM_ARPARTNER.ARSUBPARTNERSUBSECTORCODE IS 'Subsector classification at sub-partner level';
COMMENT ON COLUMN DIM_ARPARTNER.CURRENTFLAG IS 'Flag indicating whether the record is currently active: 1 = Active (current); 0 = Inactive (historical).';
COMMENT ON COLUMN DIM_ARPARTNER.DELETEDFLAG IS 'Flag indicating whether the record has been logically deleted (soft delete): 1 = Deleted; 0 = Not deleted.';
COMMENT ON COLUMN DIM_ARPARTNER.SCDSTARTDATETIME IS 'Date and time when this record became effective (GMT/UTC timezone).';
COMMENT ON COLUMN DIM_ARPARTNER.SCDENDDATETIME IS 'Date and time when this record was superseded by another record (GMT/UTC timezone).';
COMMENT ON COLUMN DIM_ARPARTNER.LATEARRIVINGFLAG IS 'Flag indicating whether the record was inserted by a fact table before the profile was loaded into the Dim: 1 = Late arriving (e.g., created by a fact load, not a dimension load); 0 = Normal ingestion process.';
COMMENT ON COLUMN DIM_ARPARTNER.TYPE1HASH IS "Hashkey of all concatenated columns excluding SID's and technical fields.";
COMMENT ON COLUMN DIM_ARPARTNER.TYPE2HASH IS "Hashkey of all concatenated columns excluding SID's and technical fields.";
COMMENT ON COLUMN DIM_ARPARTNER.CREATEDBATCHLOGID IS 'ID number of the bach that created the record.';
COMMENT ON COLUMN DIM_ARPARTNER.UPDATEDBATCHLOGID IS 'ID number of the bach that updated the record.';
COMMENT ON COLUMN DIM_ARPARTNER.UPDATETYPE IS 'Type of update of the record.';


COMMENT ON TABLE DIM_PNR IS 'Stores Passenger Name Record (PNR) information from the airline reservation system. Each PNR represents a booking/reservation and contains metadata about which offices created, own, and last modified the reservation. The table tracks the history of PNR attribute changes.';
COMMENT ON COLUMN DIM_PNR.PNRSID IS 'Surrogate key of a unique PNR record in the dimension table';
COMMENT ON COLUMN DIM_PNR.PNRHASHKEY IS 'Hashkey of a unique PNR record in the dimension table';
COMMENT ON COLUMN DIM_PNR.PNRUNIQUECODE IS 'Unique identifier combining PNR locator and PNR booking date';
COMMENT ON COLUMN DIM_PNR.PNRCODE IS '6-character alphanumeric booking reference code, also called PNR Locator';
COMMENT ON COLUMN DIM_PNR.PNRBOOKINGUTCDATETIME IS 'Booking timestamp in GMT/UTC when the PNR reservation was created';
COMMENT ON COLUMN DIM_PNR.OWNEROFFICEAGENTTYPECODE IS 'Code identifying the type of system or office that owns the PNR';
COMMENT ON COLUMN DIM_PNR.OWNEROFFICEIATACODE IS 'IATA code of the system or office that owns the PNR';
COMMENT ON COLUMN DIM_PNR.OWNEROFFICEAMADEUSCODE IS 'Amadeus office ID of the PNR owner';
COMMENT ON COLUMN DIM_PNR.OWNEROFFICESYSTEMCODE IS "System code identifying the owning office's booking system";
COMMENT ON COLUMN DIM_PNR.CREATIONOFFICEAGENTTYPECODE IS 'Agent type code of the office that originally created the PNR';
COMMENT ON COLUMN DIM_PNR.CREATIONOFFICEIATACODE IS 'IATA code of the office that created the booking';
COMMENT ON COLUMN DIM_PNR.CREATIONOFFICESYSTEMCODE IS 'System code of the office that created the PNR';
COMMENT ON COLUMN DIM_PNR.CREATIONOFFICEAMADEUSCODE IS 'Amadeus office ID where the PNR was originally created';
COMMENT ON COLUMN DIM_PNR.CREATIONOFFICEDATETIMESTAMP IS 'Timestamp when the PNR was created in the creation office';
COMMENT ON COLUMN DIM_PNR.LASTMODIFICATIONOFFICEAGENTTYPECODE IS 'Agent type of the office that last modified the PNR';
COMMENT ON COLUMN DIM_PNR.LASTMODIFICATIONOFFICEAMADEUSCODE IS 'Amadeus office ID that last modified the PNR';
COMMENT ON COLUMN DIM_PNR.LASTMODIFICATIONOFFICEIATACODE IS 'IATA code of the office that last modified the PNR';
COMMENT ON COLUMN DIM_PNR.LASTMODIFICATIONOFFICESYSTEMCODE IS 'System code of the office that last modified the PNR';
COMMENT ON COLUMN DIM_PNR.QUEUINGOFFICENAME IS 'Name of the office where PNR is queued for processing/action';
COMMENT ON COLUMN DIM_PNR.CURRENTFLAG IS 'Indicates if this is the current/active version of the record';
COMMENT ON COLUMN DIM_PNR.DELETEDFLAG IS 'Indicates if the record has been logically deleted';
COMMENT ON COLUMN DIM_PNR.SCDSTARTDATETIME IS 'Timestamp when this version of the record became effective';
COMMENT ON COLUMN DIM_PNRSCDENDDATETIME IS 'Timestamp when this version expired (end date for SCD Type 2)';
COMMENT ON COLUMN DIM_PNRLATEARRIVINGFLAG IS 'Indicates if the record arrived late in the ETL process';
COMMENT ON COLUMN DIM_PNRTYPE1HASH IS 'Hash of Type 1 (overwrite) attributes for change detection';
COMMENT ON COLUMN DIM_PNRTYPE2HASH IS 'Hash of Type 2 (historical) attributes for change detection';
COMMENT ON COLUMN DIM_PNRCREATEDBATCHLOGID IS 'Batch log identifier for the ETL process that created this record';
COMMENT ON COLUMN DIM_PNRUPDATEDBATCHLOGID IS 'Batch log identifier for the ETL process that last updated this record';
COMMENT ON COLUMN DIM_PNR.UPDATETYPE IS 'Type of update operation performed';

COMMENT ON TABLE DIM_AUTHORIZATION IS 'Stores payment authorization information for Aeroplan transactions generated by the loyalty payment processor (LPP). Each authorization represents a loyalty payment  approval processed during a booking or ticketing process (air and non-air). The table also links individual authorizations to their primary/parent authorization.';
COMMENT ON COLUMN DIM_AUTHORIZATION.AUTHORIZATIONSID IS 'Surrogate key of a unique loyalty payment authorization record in the dimension table';
COMMENT ON COLUMN DIM_AUTHORIZATION.AUTHORIZATIONHASHKEY IS 'Hashkey of a unique loyalty payment authorization record in the dimension table';
COMMENT ON COLUMN DIM_AUTHORIZATION.AUTHORIZATIONID IS 'Unique identifier of a loyalty payment authorization transaction';
COMMENT ON COLUMN DIM_AUTHORIZATION.PRIMARYAUTHORIZATIONID IS 'Reference to the parent/primary authorization ID, useful when an authorization gets modified';
COMMENT ON COLUMN DIM_AUTHORIZATION.CURRENTFLAG IS 'Indicates if this is the current/active version of the record';
COMMENT ON COLUMN DIM_AUTHORIZATION.DELETEDFLAG IS 'Indicates if the record has been logically deleted';
COMMENT ON COLUMN DIM_AUTHORIZATION.SCDSTARTDATETIME IS 'Timestamp when this version of the record became effective';
COMMENT ON COLUMN DIM_AUTHORIZATION.SCDENDDATETIME IS 'Timestamp when this version expired (end date for SCD Type 2)';
COMMENT ON COLUMN DIM_AUTHORIZATION.LATEARRIVINGFLAG IS 'Indicates if the record arrived late in the ETL process';
COMMENT ON COLUMN DIM_AUTHORIZATION.TYPE1HASH IS 'Hash of Type 1 (overwrite) attributes for change detection';
COMMENT ON COLUMN DIM_AUTHORIZATION.TYPE2HASH IS 'Hash of Type 2 (historical) attributes for change detection';
COMMENT ON COLUMN DIM_AUTHORIZATION.CREATEDBATCHLOGID IS 'Batch log identifier for the ETL process that created this record';
COMMENT ON COLUMN DIM_AUTHORIZATION.UPDATEDBATCHLOGID IS 'Batch log identifier for the ETL process that last updated this record';
COMMENT ON COLUMN DIM_AUTHORIZATION.UPDATETYPE IS 'Type of update operation performed';

COMMENT ON TABLE DIM_CAMPAIGN_ASSIGNMENT IS  'Contains descriptive information about work assignments linking users, roles, or teams to campaign work items.';
COMMENT ON TABLE DIM_CAMPAIGN_OPTASK IS  'Contains descriptive information about campaign issues, requests, risks, blockers, and other work items.';
COMMENT ON TABLE DIM_CAMPAIGN_PORTFOLIO IS  'Contains descriptive information about portfolios used to organize campaign programs and projects.';
COMMENT ON TABLE DIM_CAMPAIGN_PORTFOLIO_PARAMETER IS  'Contains descriptive information about custom user-defined fields used to capture campaign-specific attributes at portfolio level';
COMMENT ON TABLE DIM_CAMPAIGN_PROGRAM IS  'Contains descriptive information about programs that group related projects. At marketing campaign level';
COMMENT ON TABLE DIM_CAMPAIGN_PROGRAM_PARAMETER IS  'Contains descriptive information about custom user-defined fields used to capture campaign-specific attributes at program level';
COMMENT ON TABLE DIM_CAMPAIGN_PROJECT IS  'Contains descriptive information about campaign projects, including ownership, status, and planning attributes.';
COMMENT ON TABLE DIM_CAMPAIGN_PROJECT_PARAMETER IS  'Contains descriptive information about custom user-defined fields used to capture campaign-specific attributes at project level';
COMMENT ON TABLE DIM_CAMPAIGN_ROLE IS  'Contains descriptive information about job functions used for resource planning and work assignments.';
COMMENT ON TABLE DIM_CAMPAIGN_TASK IS  'Contains descriptive information about campaign tasks and their associated attributes.';
COMMENT ON TABLE DIM_CAMPAIGN_TASK_PARAMETER IS  'Contains descriptive information about custom user-defined fields used to capture campaign-specific attributes at task level';
COMMENT ON TABLE DIM_CAMPAIGN_TEAM IS  'Contains descriptive information about teams used for collaboration and workload management.';
COMMENT ON TABLE DIM_CAMPAIGN_USER IS  'Contains descriptive information about users who create, manage, review, approve, or complete campaign work.';
COMMENT ON TABLE FACT_CAMPAIGN_ASSIGNMENT IS  'Contains activity data related to campaign work assignments.';
COMMENT ON TABLE FACT_CAMPAIGN_OPTASK IS  'Contains activity data related to campaign issues and requests.';
COMMENT ON TABLE FACT_CAMPAIGN_PROJECT IS  'Contains activity data related to campaign project execution and delivery.';
COMMENT ON TABLE FACT_CAMPAIGN_TASK IS  'Contains activity data related to campaign task execution and completion.';









